package com.abulubad.sojourn.core.network.dto

import kotlinx.serialization.Serializable

/**
 * The seed catalogue as it is stored (`catalog.json`) and served (`/catalog/catalog.json` on the docs site).
 * Amounts are minor units (pence, cents, centimes); dates are ISO-8601; photos are paths under [photoBase].
 * Generated by `tooling/scripts/make_catalog.py`.
 */
@Serializable
data class CatalogDto(
    val version: Int,
    val photoBase: String,
    val cities: List<CityDto>,
    val stays: List<StayDto>,
)

@Serializable
data class CityDto(
    val id: String,
    val countryCode: String,
    val currency: String,
    val latitude: Double,
    val longitude: Double,
    val photo: String,
)

@Serializable
data class HostTextDto(val text: String, val lang: String)

@Serializable
data class FactsDto(val bedrooms: Int, val beds: Int, val bathrooms: Int, val sleeps: Int)

@Serializable
data class RatingDto(val score: Double, val count: Int)

@Serializable
data class AreaDto(val latitude: Double, val longitude: Double, val radiusMetres: Int)

/** Nightly rate and fees. A long-stay discount applies from [longStayMinNights]; city tax is per night. */
@Serializable
data class PricingDto(
    val currency: String,
    val nightly: Long,
    val cleaningFee: Long = 0,
    val cityTaxPerNight: Long = 0,
    val longStayDiscountPercent: Int? = null,
    val longStayMinNights: Int = DEFAULT_LONG_STAY_NIGHTS,
) {
    private companion object {
        const val DEFAULT_LONG_STAY_NIGHTS = 28
    }
}

/** Policies with their numbers (N-03); none can be stated without one. */
@Serializable
data class PoliciesDto(
    val freeCancellationDaysBefore: Int,
    val deposit: Long,
    val depositRefundable: Boolean = true,
    val checkInFrom: String,
    val checkInMethod: String,
    val checkOutBy: String,
    val minimumNights: Int,
)

@Serializable
data class DateRangeDto(val start: String, val end: String)

@Serializable
data class StayDto(
    val id: String,
    val cityId: String,
    val areaKey: String,
    val title: HostTextDto,
    val description: HostTextDto,
    val facts: FactsDto,
    val photos: List<String>,
    val amenities: List<String>,
    val policies: PoliciesDto,
    val rating: RatingDto? = null,
    val area: AreaDto,
    val pricing: PricingDto,
    val walkMinutesToTransit: Int? = null,
    val instantBook: Boolean = false,
    val blocked: List<DateRangeDto> = emptyList(),
)
